const selectionTrack=document.getElementById('selectionBgm');
const bgmTracks=[...stageTracks,...bossTracks,selectionTrack];
const selectionVolume=.34;
let unlocked=false,playRequest=null,awaitingGesture=false;
let current=null, currentStage=-1, bossMode=false, appearancePending=-1;

function play(a,volume){
  if(!a||!isMusicOn())return;
  if(current!==a){
    if(current){current.pause();current.currentTime=0}
    current=a;
    a.volume=0;
    a.currentTime=0;
    a.play().catch(()=>{});
  } else if(a.paused){a.play().catch(()=>{})}
  a.volume=Math.min(volume,Math.max(0,a.volume+.025));
}

// One owner for menu/stage/boss music; no play request survives a scene change.
function pauseMusic(){
  for(const track of bgmTracks)track.pause();
  playRequest=null;
}
function desiredMusic(){
  if(document.hidden||!isMusicOn())return null;
  if(started)return boss?bossTracks[stage]:stageTracks[stage];
  return !gameOverPending&&!menu.classList.contains('hidden')?selectionTrack:null;
}
function play(a,volume){
  if(!a||!isMusicOn()||document.hidden)return;
  if(current!==a){
    pauseMusic();
    if(current)current.currentTime=0;
    current=a;awaitingGesture=false;
    a.volume=0;a.currentTime=0;
  }
  a.volume=a===selectionTrack?selectionVolume:Math.min(volume,Math.max(0,a.volume+.025));
  if(!unlocked||awaitingGesture||playRequest||!a.paused)return;
  const request={track:a};playRequest=request;
  try{
    Promise.resolve(a.play()).then(()=>{
      if(playRequest===request)playRequest=null;
      if(current!==a||desiredMusic()!==a)a.pause();
    }).catch(()=>{
      if(playRequest===request){playRequest=null;awaitingGesture=true;}
    });
  }catch(error){
    if(playRequest===request){playRequest=null;awaitingGesture=true;}
  }
}
function syncMusic(){
  const target=desiredMusic();
  if(!target){pauseMusic();return;}
  play(target,target===selectionTrack?selectionVolume:boss?.58:.42);
}
function userGesture(event){
  if(!event.isTrusted)return;
  unlocked=true;awaitingGesture=false;
  // The existing click handlers finish Start/toggle before choosing a track.
  if(event.target.closest?.('#startSelected,#musicToggle'))return;
  syncMusic();
}
document.addEventListener('pointerdown',userGesture,{capture:true});
document.addEventListener('keydown',userGesture,{capture:true});
document.addEventListener('click',event=>{
  if(event.isTrusted){unlocked=true;awaitingGesture=false;syncMusic();}
});
new MutationObserver(syncMusic).observe(menu,{attributes:true,attributeFilter:['class']});

oldResume();
if(isMusicOn()){
  const a=stageTracks[0];
  a.volume=.42;
  a.play().catch(()=>{});
  current=a;
  currentStage=0;
}

oldResume();
// start() calls resume before setting started/menu: stop menu music here.
pauseMusic();
if(current)current.currentTime=0;
current=null;currentStage=0;bossMode=false;appearancePending=-1;
if(isMusicOn()){
  play(stageTracks[0],.42);
  stageTracks[0].volume=.42;
}

gameAudio.pause=function(){
  for(const a of [...stageTracks,...bossTracks])a.pause();
  for(const a of Object.values(effects))a.pause();
  current=null;currentStage=-1;bossMode=false;appearancePending=-1;
  oldPause();
};

gameAudio.pause=function(){
  pauseMusic();
  for(const a of Object.values(effects))a.pause();
  current=null;currentStage=-1;bossMode=false;appearancePending=-1;
  oldPause();
};
